import { precacheAndRoute, cleanupOutdatedCaches } from 'workbox-precaching';
import { registerRoute } from 'workbox-routing';
import { NetworkFirst, CacheFirst } from 'workbox-strategies';
import { ExpirationPlugin } from 'workbox-expiration';
import { CacheableResponsePlugin } from 'workbox-cacheable-response';

// Precache all assets generated by your build process
precacheAndRoute(self.__WB_MANIFEST);

// Cleanup outdated caches
cleanupOutdatedCaches();

// Runtime caching for API requests
registerRoute(
  /^https:\/\/eventai-server\.munymunyhom\.tech\/api\/.*/i,
  new NetworkFirst({
    cacheName: 'api-cache',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 50,
        maxAgeSeconds: 5 * 60 // 5 minutes
      }),
      new CacheableResponsePlugin({
        statuses: [0, 200]
      })
    ]
  })
);

// Runtime caching for Google Maps
registerRoute(
  /^https:\/\/maps\.googleapis\.com\/.*/i,
  new CacheFirst({
    cacheName: 'google-maps-cache',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 50,
        maxAgeSeconds: 60 * 60 * 24 * 7 // 1 week
      })
    ]
  })
);

// =============================================
// PUSH NOTIFICATION HANDLERS
// =============================================

// Listen for push notifications from the backend
self.addEventListener('push', (event) => {
  console.log('📩 Push notification received:', event);

  if (!event.data) {
    console.warn('Push event has no data');
    return;
  }

  try {
    const data = event.data.json();
    console.log('📬 Push notification data:', data);

    const title = data.title || 'EventBuddy Notification';
    const options = {
      body: data.body || data.message || 'You have a new notification',
      icon: data.icon || '/pwa-192x192.png',
      badge: data.badge || '/pwa-64x64.png',
      image: data.image,
      tag: data.tag || 'default',
      data: data.data || {},
      requireInteraction: data.requireInteraction || false,
      actions: data.actions || [],
      vibrate: data.vibrate || [200, 100, 200],
      timestamp: Date.now()
    };

    event.waitUntil(
      self.registration.showNotification(title, options)
        .then(() => {
          console.log('✅ Notification displayed successfully');
        })
        .catch((error) => {
          console.error('❌ Error displaying notification:', error);
        })
    );
  } catch (error) {
    console.error('❌ Error parsing push data:', error);
    
    // Fallback: show a generic notification
    event.waitUntil(
      self.registration.showNotification('EventBuddy', {
        body: 'You have a new notification',
        icon: '/pwa-192x192.png',
        badge: '/pwa-64x64.png'
      })
    );
  }
});

// Handle notification clicks
self.addEventListener('notificationclick', (event) => {
  console.log('🔔 Notification clicked:', event);
  
  event.notification.close();

  // Get the URL to open from notification data
  const urlToOpen = event.notification.data?.url || '/';
  const fullUrl = new URL(urlToOpen, self.location.origin).href;

  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true })
      .then((clientList) => {
        // Check if there's already a window open with the target URL
        for (const client of clientList) {
          if (client.url === fullUrl && 'focus' in client) {
            return client.focus();
          }
        }
        
        // If no matching window is open, check if any window is open
        if (clientList.length > 0) {
          const client = clientList[0];
          if ('focus' in client) {
            return client.focus().then(() => {
              // Navigate the focused window to the target URL
              if ('navigate' in client) {
                return client.navigate(fullUrl);
              }
            });
          }
        }
        
        // If no window is open, open a new one
        if (clients.openWindow) {
          return clients.openWindow(fullUrl);
        }
      })
      .catch((error) => {
        console.error('❌ Error handling notification click:', error);
      })
  );
});

// Handle notification close
self.addEventListener('notificationclose', (event) => {
  console.log('🔕 Notification closed:', event);
  
  // Track notification dismissals if needed
  const data = event.notification.data;
  if (data?.trackDismissal) {
    console.log('Notification dismissed:', data);
    // You can send analytics or tracking data here
  }
});

// Handle push subscription changes
self.addEventListener('pushsubscriptionchange', (event) => {
  console.log('🔄 Push subscription changed');
  
  event.waitUntil(
    self.registration.pushManager.subscribe(event.oldSubscription.options)
      .then((subscription) => {
        console.log('✅ Resubscribed to push notifications');
        // Send the new subscription to your backend
        return fetch('/api/notifications/subscribe', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(subscription.toJSON())
        });
      })
      .catch((error) => {
        console.error('❌ Error resubscribing:', error);
      })
  );
});

console.log('🚀 Custom service worker with push notifications loaded');

